namespace Inventory;

/// <summary>Builds a replenishment plan across a set of stock items.</summary>
public sealed class ReplenishmentPlanner
{
    public IReadOnlyList<string> BuildPlan(IEnumerable<StockItem> items, ISupplier supplier, int season)
    {
        var plan = new List<string>();
        foreach (var item in items)
        {
            if (!TryCalculateOrderQuantity(item, season, out var quantity))
                continue;

            var placed = supplier.PlaceOrder(item.Sku, quantity);
            plan.Add(FormatResult(item.Sku, quantity, placed));
        }
        return plan;
    }

    private static bool TryCalculateOrderQuantity(StockItem item, int season, out int quantity)
    {
        quantity = 0;
        if (item.OnHand < 0 || string.IsNullOrEmpty(item.Sku)) return false;

        var available = item.OnHand - item.Reserved;
        if (available > item.ReorderPoint) return false;

        quantity = CalculateBaseQuantity(item.ReorderPoint - available);
        quantity = ApplySeasonalAdjustment(quantity, season);
        return quantity > 0;
    }

    private static int CalculateBaseQuantity(int deficit) => deficit switch
    {
        <= 0 => 0,
        < 10 => 10,
        < 100 => deficit,
        _ => deficit + 50
    };

    private static int ApplySeasonalAdjustment(int quantity, int season)
    {
        if (season == 4 && quantity > 0)
            return (int)(quantity * 1.5);
        if (season == 1)
            return quantity / 2;
        return quantity;
    }

    private static string FormatResult(string sku, int quantity, bool placed)
    {
        if (!placed)
            return $"{sku}:FAILED";
        if (quantity > 200)
            return $"{sku}:LARGE:{quantity}";
        return $"{sku}:{quantity}";
    }
}
